package local.atmospherevisual;
import me.cryo.zombierool.client.*;
import me.cryo.zombierool.gameplay.*;
import net.minecraft.client.Minecraft;
import net.minecraft.core.BlockPos;
import net.minecraftforge.common.MinecraftForge;
import net.minecraftforge.event.TickEvent;
import net.minecraftforge.fml.common.Mod;
@Mod("atmospherevisual")
public final class AmbientParticlesVisualTest {
 boolean requested,done;int age,checks,visiblePixels;volatile String failure;int[] baseline,wall;
 public AmbientParticlesVisualTest(){MinecraftForge.EVENT_BUS.addListener(this::tick);}
 void check(boolean v,String label){if(!v)throw new AssertionError(label);checks++;System.out.println("ATMOSPHERE VISUAL CHECK: "+label);}
 void server(java.util.function.Consumer<net.minecraft.server.level.ServerPlayer> action){var mc=Minecraft.getInstance();mc.getSingleplayerServer().execute(()->{try{action.accept(mc.getSingleplayerServer().getPlayerList().getPlayers().get(0));}catch(Throwable t){failure=t.toString();t.printStackTrace();}});}
 int[] shot(String name)throws Exception{try(var image=net.minecraft.client.Screenshot.takeScreenshot(Minecraft.getInstance().getMainRenderTarget())){if(image.getWidth()!=1280||image.getHeight()!=720)throw new AssertionError("Capture size");int[] data=new int[1280*720];for(int y=0;y<720;y++)for(int x=0;x<1280;x++)data[y*1280+x]=image.getPixelRGBA(x,y);image.writeToFile(java.nio.file.Path.of(System.getProperty("atmosphere.output"),name+".png"));return data;}}
 int changed(int[] a,int[] b){return changed(a,b,false);}
 int changed(int[] a,int[] b,boolean wallOnly){int count=0;for(int y=wallOnly?220:60;y<(wallOnly?480:500);y++)for(int x=wallOnly?300:180;x<(wallOnly?850:1100);x++){int c=a[y*1280+x],d=b[y*1280+x];if(Math.abs((c&255)-(d&255))+Math.abs((c>>8&255)-(d>>8&255))+Math.abs((c>>16&255)-(d>>16&255))>80)count++;}return count;}
 void tick(TickEvent.ClientTickEvent e){if(done||e.phase!=TickEvent.Phase.END)return;var mc=Minecraft.getInstance();if(mc.getOverlay()!=null)return;try{
  if(failure!=null)throw new AssertionError(failure);if(!requested){requested=true;mc.options.pauseOnLostFocus=false;org.lwjgl.glfw.GLFW.glfwHideWindow(mc.getWindow().getWindow());mc.createWorldOpenFlows().loadLevel(mc.screen,"AtmosphereFixture");return;}
  if(mc.level==null||mc.player==null||mc.isPaused())return;if(mc.getMainRenderTarget().width!=1280){mc.getWindow().setWidth(1280);mc.getWindow().setHeight(720);mc.resizeDisplay();}age++;
  if(age==20){mc.options.hideGui=false;ClientEnvironmentEffects.handleWeatherSync(false,"","normal","global");server(p->{var l=p.serverLevel();p.setGameMode(net.minecraft.world.level.GameType.CREATIVE);p.getInventory().clearContent();for(var at:BlockPos.betweenClosed(-6,72,25,6,86,36))l.setBlock(at,at.getY()==72?net.minecraft.world.level.block.Blocks.STONE.defaultBlockState():net.minecraft.world.level.block.Blocks.AIR.defaultBlockState(),3);p.teleportTo(l,0.5,73,32.5,180,-15);});}
  if(age==180){ClientEnvironmentEffects.setFogPreset("none",0,0,0,.5f,512);var n=MapAtmosphere.preset("moon");n.put("skyObjects",new net.minecraft.nbt.ListTag());n.put("sources",new net.minecraft.nbt.ListTag());for(String key:new String[]{"grain","dirt","vignette","exposure"})n.putDouble(key,0);for(String key:new String[]{"contrast","gamma","saturation"})n.putDouble(key,1);MapAtmosphereClient.receive("preview",n);}
  if(age==201){check(MapAtmosphereClient.deferredBlood()==Boolean.getBoolean("atmosphere.shaders"),"Ambient rendering selects the correct plain/shader sky pass");System.out.println("AMBIENT CAMERA "+mc.player.position()+" yaw="+mc.player.getYRot()+" pitch="+mc.player.getXRot());baseline=shot("ambient-sky-baseline");}
  if(age==204){for(int i=0;i<12;i++)AmbientParticles.spawn(net.minecraft.core.particles.ParticleTypes.CLOUD,-.6+i*.2,75.5,29.5,0,0,0);var f=AmbientParticles.class.getDeclaredField("LIVE");f.setAccessible(true);System.out.println("AMBIENT COUNT "+((java.util.Set<?>)f.get(null)).size());}
  if(age==210){System.out.println("AMBIENT ENGINE "+mc.particleEngine.countParticles()+" camera="+mc.gameRenderer.getMainCamera().getPosition());var f=AmbientParticles.class.getDeclaredField("LIVE");f.setAccessible(true);System.out.println("AMBIENT COUNT "+((java.util.Set<?>)f.get(null)).size());visiblePixels=changed(baseline,shot("ambient-clouds-visible"));System.out.println("AMBIENT PIXELS visible="+visiblePixels);check(visiblePixels>40,"Cloud particles remain visible against the custom sky");server(p->{for(var at:BlockPos.betweenClosed(-6,73,31,6,86,31))p.serverLevel().setBlock(at,net.minecraft.world.level.block.Blocks.STONE.defaultBlockState(),3);});}
  if(age==234){wall=shot("ambient-clouds-behind-wall");var field=AmbientParticles.class.getDeclaredField("LIVE");field.setAccessible(true);for(var p:java.util.List.copyOf((java.util.Set<net.minecraft.client.particle.Particle>)field.get(null)))p.remove();}
  if(age==240){int delta=changed(wall,shot("ambient-wall-without-clouds"),true);System.out.println("AMBIENT PIXELS through-wall="+delta);check(delta<100,"Opaque scenery still hides the ambient particles");var field=AmbientParticles.class.getDeclaredField("ALL");field.setAccessible(true);var all=(java.util.Map<net.minecraft.client.particle.Particle,?>)field.get(null);mc.options.particles().set(net.minecraft.client.ParticleStatus.ALL);AmbientParticles.emissionBudget(35);for(int i=0;i<10000;i++)AmbientParticles.spawn(net.minecraft.core.particles.ParticleTypes.CLOUD,.5,75,40,0,0,0);check(AmbientParticles.activeCount()==896,"Ten thousand emission requests stay within the dense ambient budget");var particle=all.keySet().iterator().next();AmbientParticles.prepareFrame(true);var bean=(com.sun.management.ThreadMXBean)java.lang.management.ManagementFactory.getThreadMXBean();long thread=Thread.currentThread().getId(),before=bean.getThreadAllocatedBytes(thread),start=System.nanoTime();for(int i=0;i<50000;i++)AmbientParticles.defer(particle);long allocated=bean.getThreadAllocatedBytes(thread)-before;System.out.println("AMBIENT HOT PATH: "+allocated+" bytes for 50000 checks in "+((System.nanoTime()-start)/1000000.0)+" ms");check(allocated<65536,"Per-particle render checks avoid resource lookups and allocations");for(var particleToRemove:java.util.List.copyOf(all.keySet()))particleToRemove.remove();AmbientParticles.tick(new TickEvent.ClientTickEvent(TickEvent.Phase.END));mc.options.particles().set(net.minecraft.client.ParticleStatus.MINIMAL);AmbientParticles.emissionBudget(35);for(int i=0;i<1000;i++)AmbientParticles.spawn(net.minecraft.core.particles.ParticleTypes.CLOUD,.5,75,40,0,0,0);check(AmbientParticles.activeCount()==224,"Minimal particle setting reduces the dense ambient budget to 224");mc.options.particles().set(net.minecraft.client.ParticleStatus.ALL);done=true;System.out.println("ATMOSPHERE VISUAL PASS: "+checks+" ambient-particle checks");mc.stop();}
 }catch(Throwable t){t.printStackTrace();done=true;System.out.println("ATMOSPHERE VISUAL FAIL: "+t);mc.stop();}}
}
